import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int n = Integer.parseInt(br.readLine().trim());
        String inputLine = br.readLine();

        String regexPattern = "\\([\\w_]*\\)";
        String[] segments = inputLine.split(regexPattern);
        int maxWordLen = 0;
        for (String segment : segments) {
            int maxInSegment = Arrays.stream(segment.split("_"))
                                     .mapToInt(String::length)
                                     .max()
                                     .orElse(0);
            if (maxInSegment > maxWordLen) {
                maxWordLen = maxInSegment;
            }
        }

        Pattern pattern = Pattern.compile(regexPattern);
        Matcher matcher = pattern.matcher(inputLine);
        long insideCount = 0;
        while (matcher.find()) {
            String inside = matcher.group().substring(1, matcher.group().length() - 1);
            insideCount += Arrays.stream(inside.split("_"))
                                 .filter(s -> !s.isEmpty())
                                 .count();
        }
        out.println(maxWordLen + " " + insideCount);
        out.close();
    }
}
