#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cin.ignore(); // To consume the newline after the integer input
    string inputLine;
    getline(cin, inputLine);

    regex pattern("\\([\\w_]*\\)");
    vector<string> segments;
    sregex_token_iterator iter(inputLine.begin(), inputLine.end(), pattern, -1);
    sregex_token_iterator end;
    for (; iter != end; ++iter) {
        segments.push_back(*iter);
    }

    int maxWordLen = 0;
    for (const auto& segment : segments) {
        int maxInSegment = 0;
        stringstream ss(segment);
        string token;
        while (getline(ss, token, '_')) {
            if (!token.empty()) {
                maxInSegment = max(maxInSegment, (int)token.length());
            }
        }
        if (maxInSegment > maxWordLen) {
            maxWordLen = maxInSegment;
        }
    }

    long long insideCount = 0;
    auto matches_begin = sregex_iterator(inputLine.begin(), inputLine.end(), pattern);
    auto matches_end = sregex_iterator();

    for (auto it = matches_begin; it != matches_end; ++it) {
        string inside = (*it)[0].str().substr(1, (*it)[0].length() - 2);
        stringstream ss(inside);
        string s;
        while (getline(ss, s, '_')) {
            if (!s.empty()) {
                insideCount++;
            }
        }
    }

    cout << maxWordLen << " " << insideCount << "\n";

    return 0;
}
